#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

class Solution {
public:
    long long minTime(vector<int>& skill, vector<int>& mana) {
        long long sumSkill = accumulate(skill.begin(), skill.end(), 0LL);
        long long prevWizardDone = sumSkill * mana[0];

        for (size_t j = 1; j < mana.size(); ++j) {
            long long prevPotionDone = prevWizardDone;
            for (int i = (int)skill.size() - 2; i >= 0; --i) {
                prevPotionDone -= (long long)skill[i + 1] * mana[j - 1];
                prevWizardDone = max(prevPotionDone, prevWizardDone - (long long)skill[i] * mana[j]);
            }
            prevWizardDone += sumSkill * mana[j];
        }

        return prevWizardDone;
    }
};

class Solution {
    public long minTime(int[] skill, int[] mana) {
        long sumSkill = 0;
        for (int s : skill) sumSkill += s;

        long prevWizardDone = sumSkill * mana[0];

        for (int j = 1; j < mana.length; j++) {
            long prevPotionDone = prevWizardDone;
            for (int i = skill.length - 2; i >= 0; i--) {
                prevPotionDone -= (long) skill[i + 1] * mana[j - 1];
                prevWizardDone = Math.max(prevPotionDone, prevWizardDone - (long) skill[i] * mana[j]);
            }
            prevWizardDone += sumSkill * mana[j];
        }

        return prevWizardDone;
    }
}

var minTime = function(skill, mana) {
    const sumSkill = skill.reduce((acc, x) => acc + BigInt(x), 0n);
    let prevWizardDone = sumSkill * BigInt(mana[0]);

    for (let j = 1; j < mana.length; j++) {
        let prevPotionDone = prevWizardDone;
        for (let i = skill.length - 2; i >= 0; i--) {
            prevPotionDone -= BigInt(skill[i + 1]) * BigInt(mana[j - 1]);
            const candidate = prevWizardDone - BigInt(skill[i]) * BigInt(mana[j]);
            if (candidate > prevPotionDone) {
                prevWizardDone = candidate;
            } else {
                prevWizardDone = prevPotionDone;
            }
        }
        prevWizardDone += sumSkill * BigInt(mana[j]);
    }

    return Number(prevWizardDone);
};
